CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, endpoint TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, teams TEXT NOT NULL, prefs TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS matches (id TEXT PRIMARY KEY, state TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS native_subs (id TEXT PRIMARY KEY, token TEXT NOT NULL, env TEXT NOT NULL, teams TEXT NOT NULL, prefs TEXT NOT NULL, start_token TEXT, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS activities (id TEXT NOT NULL, match_id TEXT NOT NULL, token TEXT NOT NULL, env TEXT NOT NULL, updated INTEGER NOT NULL, PRIMARY KEY (id, match_id));
